    /// <summary>
    /// Get last Activity record
    /// MPJ_22159 Collections note DCP 12/04/2022
    /// </summary>
    /// <returns>Activity record</returns>
    public smmActivities METGetActivityFields()
    {
        smmActivities               METActivity;
        smmActivityParentLinkTable  METActivityParent;

        select firstOnly activityNumber, Purpose, TypeId, UserMemo, CreatedBy, CreatedDateTime
            from    METActivity
            order by CreatedDateTime desc

            exists join METActivityParent
            where   METActivityParent.ActivityNumber    == METActivity.ActivityNumber
            &&     (METActivityParent.ParentType        == smmActivityParentType::Customer
                 || METActivityParent.ParentType        == smmActivityParentType::Collections)
            &&      METActivityParent.RefRecId          == this.RecId
            &&      METActivityParent.RefTableId        == tableNum(CustTable);

        return METActivity;
    }

    /// <summary>
    /// Get community chest emails
    /// MPJ-15936 Customer Group Name DCP 20/06/2022
    /// </summary>
    /// <returns>Email</returns>
    [SysClientCacheDataMethod]
    public display Email emails()
    {
        str addresses;
        
        LogisticsIProvider logisticsProvider = LogisticsProviderFactory::getLogisticsProvider();

        if (logisticsProvider)
        {
            addresses = con2Str(logisticsProvider.electronicAddressLocatorsByRole(this.Party, METConstants::CommunityChestRole), METConstants::AddressSeperator);
        }

        return addresses;
    }

/// <summary>
/// Code added by TCS to make value for Exclude interest charge to YES
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(CustTable), DataEventType::Inserting)]
public static void CustTable_onInserting(Common sender, DataEventArgs e)
{
    CustTable cTable = sender as CustTable;
    cTable.CustExcludeInterestCharges = NoYes::Yes;
}

    /// <summary>
    /// CB503_CustomerNumbering
    /// Retrieves the numbersequenceformhandler that can be used in the form creation of this entity
    /// to generate the numbersequence related field
    /// </summary>
    /// <param name="callerForm">
    /// The form that will be using this numbersequenceformhandler to create this entity
    /// </param>
    /// <param name="numberSequenceDatasource">
    /// The datasource that contains this entity on the creation form
    /// </param>
    /// <returns>
    /// the numbersequenceformhandler that can be used in the form creation of this entity
    /// </returns>
    public static NumberSeqFormHandler getNumberSeqFormHandler(ObjectRun callerForm, FormDataSource numberSequenceDatasource)
    {
        NumberSeqFormHandler    numberSeqFormHandler;
        FormRun callerFormRun = callerForm as FormRun;
        FormDataSource custDatasource = callerFormRun.dataSource(1);
        CustTable custTable = custDatasource.cursor();
        CustGroup custGroup = CustGroup::find(custTable.CustGroup);
        METBusinessUnit businessUnit;
        
        if (!numberSeqFormHandler || numberSeqFormHandler.parmNumberSequenceId() != CustParameters::numRefCustAccount().NumberSequenceId)
        {
            numberSeqFormHandler = NumberSeqFormHandler::newForm(CustParameters::numRefCustAccount().NumberSequenceId,
                                                                    callerForm,
                                                                    numberSequenceDatasource,
                                                                    fieldNum(CustTable, AccountNum));
        }
        
        numberSeqFormHandler = next getNumberSeqFormHandler(callerForm, numberSequenceDatasource);

        //CB503_CustomerNumbering, getting Number sequence from custom setup if enabled
        if (custGroup.METEnableCustNumbering)
        {
            businessUnit    = METBusinessUnit::findRecId(custTable.METBusinessUnitTableRefRecId);
            if (businessUnit.RecId)
            {
                if (!numberSeqFormHandler || numberSeqFormHandler.parmNumberSequenceId() != businessUnit.NumberSequenceId)
                {
                    numberSeqFormHandler = NumberSeqFormHandler::newForm(businessUnit.NumberSequenceId,
                                                                        callerForm,
                                                                        numberSequenceDatasource,
                                                                        fieldNum(CustTable, AccountNum));
                }
            }
        }
         
        return numberSeqFormHandler;
    }

    /// <summary>
    /// Verifies or sets additional field values based on the modified field.
    /// </summary>
    /// <param name = "_fieldId">The field ID of the field that was modified.</param>
    [Hookable(false)]
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(CustTable, CredManAccountStatusId) :
                this.sendCustomerStatusBusinessEvent();
                break;
        }
    }

/// <summary>
/// sends a business event on update of the customer account status
/// </summary>
internal void sendCustomerStatusBusinessEvent()
{
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METCustomerStatusChangeBusinessEvent)))
    {
        CustTable custTable = this as CustTable;
        METCustomerStatusChangeBusinessEvent::newFromCustTable(custTable).send();
    }
}

/// <summary>
/// does an Exytract number sequence exist?
/// </summary>
/// <param name = "_accountNum">Account number</param>
/// <returns>true if exists</returns>
public static boolean metExtractNumSeqExist(CustAccount _accountNum)
{
    return _accountNum
    && (select firstOnly RecId
        from custTable
        where CustTable.AccountNum == _accountNum).RecId != 0;
}

    /// <summary>
    /// CB503_CustomerNumbering
    /// get the customer number sequence
    /// </summary>
    /// <param name = "_metBusinessUnitRecId">Business unit</param>
    /// <returns>Number sequence</returns>
    public static CustAccount metGetCustomerNumSeqRec(RefRecId _metBusinessUnitRecId)
    {
        NumberSequenceCode      numberSequence;
        NumberSequenceCode      numberSeq;
        METBusinessUnit         metBusinessUnit     = METBusinessUnit::findRecId(_metBusinessUnitRecId);
        RefRecId                numberseqcust       = metBusinessUnit.NumberSequenceId;
        Integer                 businessPrefixValue = metBusinessUnit.BusinessPrefix;
        NumberSequenceTable     numberseqTable      = NumberSequenceTable::find(numberseqcust);
        METDigitLogicCheck      digitLogicCheck     = metBusinessUnit.CheckDigitLogic;
        int                     checkDigit;

        if (metBusinessUnit.RecId)
        {
            numberSeq = NumberSeq::newGetNumFromId(numberseqTable.RecId).num();

            if (metBusinessUnit.EnableStatePrefix == NoYes::Yes)
            {
                numberSequence = int2Str(businessPrefixValue) + int2Str(metBusinessUnit.StatePrefix) + numberSeq;
            }
            else
            {
                numberSequence = int2Str(businessPrefixValue) + numberSeq;
            }
            
            if (digitLogicCheck == METDigitLogicCheck::PECCD1)
            {
                checkDigit = METCheckDigitLogicHelper::getCheckDigit_One(numberSeq);
            }
            else if (digitLogicCheck == METDigitLogicCheck::PECCD2)
            {
                checkDigit = METCheckDigitLogicHelper::getCheckDigit_Two(numberSeq);
            }
            else if (digitLogicCheck == METDigitLogicCheck::PECCD5)
            {
                checkDigit = METCheckDigitLogicHelper::checkDigit_Five(numberSeq);
            }
            numberSequence =  numberSequence + int2Str(checkDigit);
        }
        if(strLen(numberSequence) > 8)
        {
            throw warning("@MET:METCustomerNumCheckDigits");
        }
        return numberSequence;
    }

    /// <summary>
    /// Validates record.
    /// </summary>
    /// <returns>If validated</returns>
    boolean validateWrite()
    {
        boolean ret = next validateWrite();

        if (this.CustGroup)
        {
            ret = this.METValidateCustOperGroupId();
        }

        return ret;
    }

    /// <summary>
    /// Validates customer operation group.
    /// </summary>
    /// <returns>If validated</returns>
    boolean METValidateCustOperGroupId()
    {
        CustGroup custGroup = CustGroup::find(this.CustGroup);
        boolean ret = true;

        if (custGroup.METCustOperGroupEnabled)
        {
            ret = this.METCustOperGroupId != '';

            if(!ret)
            {
                ret = checkFailed('@MET:CustOperGroupMissErr');
            }
        }

        return ret;
    }

    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Gets ABN verified date.
    /// </summary>
    /// <returns>ABN verified date.</returns>
    [SysClientCacheDataMethod(true)]
    public display METVerifiedDate metGetABNVerifiedDate()
    {
        TaxVATNumTable taxVatNumTable;

        select firstonly METVerifiedDate from taxVatNumTable
            where taxVatNumTable.VATNum == this.VATNum;
        
        return taxVatNumTable.METVerifiedDate;
    }

    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Validates if account status can be modified.
    /// </summary>
    /// <returns>True, if account status can be modified; otherwise, false.</returns>
    public boolean metValidateAccountStatusModified()
    {
        boolean ret;

        ret = (this.metValidateABNVerifiedDate() && this.metValidateRegistrationIdVerifiedDate());

        return ret;
    }

/// <summary>
///  CB756_ValidationOfABNToATOSystem.
///  Checks if Verified number is required or not.
/// </summary>
/// <returns>True, if verified number is required; otherwise, false.</returns>
public boolean metAccountStatusVerifiedNumberRequired()
{
    return (select firstonly RecId from credManAccountStatusTable
                where credManAccountStatusTable.CustAccountStatusId == this.CredManAccountStatusId
                &&    credManAccountStatusTable.METABNValidation    == METABNValidationType::VerifiedNumberRequired).RecId != 0;
}

    /// <summary>
    ///  CB756_ValidationOfABNToATOSystem.
    ///  Validates ABN verified date.
    /// </summary>
    /// <returns>True, if valid; otherwise, false.</returns>
    public boolean metValidateABNVerifiedDate()
    {
        boolean                   ret = true;

        if (this.metAccountStatusVerifiedNumberRequired())
        {
            if (this.metGetABNVerifiedDate() == dateNull())
            {
                ret = checkFailed(strFmt("@MET:ABNVerifiedDateError", this.AccountNum, this.CredManAccountStatusId));
            }
        }

        return ret;
    }

    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Validates Registration Id verified date.
    /// </summary>
    /// <returns>True, if valid; otherwise, false.</returns>
    public boolean metValidateRegistrationIdVerifiedDate()
    {
        DirPartyLocation                     dirPartyLocation;
        TaxRegistration                      taxRegistration;
        TaxRegistrationType                  taxRegistrationType;
        TaxRegistrationTypeApplicabilityRule taxRegistrationTypeApplicabilityRule;
        TaxRegistrationTypeCountryId         countryRegionId;
        TransDate                            transDate;
        boolean                              ret = true;
        
        if (this.metAccountStatusVerifiedNumberRequired())
        {
            transDate        = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            countryRegionId  = CompanyInfo::find().postalAddress().CountryRegionId;
        
            select firstOnly validTimeState(transDate) RegistrationNumber from taxRegistration
                join RecId from taxRegistrationTypeApplicabilityRule
                    where taxRegistration.TaxRegistrationTypeApplicabilityRule       == taxRegistrationTypeApplicabilityRule.RecId
                    &&    taxRegistrationTypeApplicabilityRule.METValidateABNWithATO == NoYes::Yes
                    &&    taxRegistrationTypeApplicabilityRule.CountryRegionId       == countryRegionId
                    &&    taxRegistration.METVerifiedDate                            == dateNull()
                join TaxRegstrationType from taxRegistrationType
                    where taxRegistrationType.RecId == taxRegistrationTypeApplicabilityRule.TaxRegistrationType
                exists join dirPartyLocation
                    where taxRegistration.DirPartyLocation == dirPartyLocation.RecId
                       && dirPartyLocation.IsPrimary       == NoYes::Yes
                       && dirPartyLocation.Party           == this.Party;
  
            if (taxRegistration.RegistrationNumber)
            {
                ret = checkFailed(strFmt("@MET:RegistationIdVerifiedDateError", this.AccountNum,
                                                                                this.CredManAccountStatusId,
                                                                                taxRegistrationType.TaxRegstrationType,
                                                                                taxRegistration.RegistrationNumber));
            }

        }
        
        return ret;
    }

    /// <summary>
    /// CB626_TMSEngineSOPackingSlip
    /// If customer is TOTE customer based on the invent parameters METAttributeIdentifiers Tote attribute records
    /// </summary>
    /// <param name = "_custAccount"Customer account</param>
    /// <param name = "_dataAreaId">Data area id</param>
    /// <returns>True if tote customer; otherzise, false.</returns>
    public static boolean METIsToteCustomer(CustAccount _custAccount, DataAreaId _dataAreaId)
    {
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;
        CustomerInstanceValue   instanceValue;
        METAttributeIdentifiers attributeIdentifiers;

        select firstonly crosscompany RecId from instanceValue
            where instanceValue.AccountNum == _custAccount
            && instanceValue.CustomerDataAreaId == _dataAreaId;

        select firstonly InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == instanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeValueText == attributeValuesTable.TextValue
                    &&  attributeIdentifiers.AttributeValueText != ''
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Customer
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::TOTE;

        return attributeValuesTable.InstanceRecId;
    }

    /// <summary>
    /// To check if the customer has Tote type (attribute type) defined under inventory parameters - Metcash - Attribute identifiers
    /// </summary>
    /// <param name = "_custAccount"Customer account</param>
    /// <param name = "_dataAreaId">Data area id</param>
    /// <returns>True if the customer has Tote type (attribute type); otherwise, false.</returns>
    public static boolean METHasToteAttributeType(CustAccount _custAccount, DataAreaId _dataAreaId)
    {
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;
        CustomerInstanceValue   instanceValue;
        METAttributeIdentifiers attributeIdentifiers;

        select firstonly crosscompany RecId from instanceValue
            where instanceValue.AccountNum == _custAccount
            && instanceValue.CustomerDataAreaId == _dataAreaId;

        select firstonly InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == instanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Customer
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::TOTE;

        return attributeValuesTable.InstanceRecId;
    }
